class Solution {
    public: int strangePrinter(string s){
        int n=s.size();
        vector<vector<int>> dp(n,vector<int>(n));
        for(int i=n-1;i>=0;--i){
            dp[i][i]=1;
            for(int j=i+1;j<n;++j){
                dp[i][j]=dp[i+1][j]+1;
                for(int k=i+1;k<=j;++k)if(s[k]==s[i])dp[i][j]=min(dp[i][j],(k==i+1?0:dp[i+1][k-1])+dp[k][j]);
            }
        }
        return dp[0][n-1];
    }
};
